  'site.stats.years': 'വർഷങ്ങളുടെ പരിചയം',
  'site.stats.projects': 'വിതരണം ചെയ്ത പ്രോജക്ടുകൾ',
  'site.stats.engineers': 'എഞ്ചിനീയർമാരും ആർക്കിടെക്ടുകളും',
