  'site.about.h3b': 'ബ്ലൂപ്രിന്റ് മുതൽ കൈമാറ്റം വരെ ഒരൊറ്റ ടീം — വിരൽചൂണ്ടൽ ഇല്ല.',
  'site.about.h4': 'ഈടുനിൽക്കാൻ പണിയുക',
  'site.about.h4b': 'ട്രെൻഡുകളെ അതിജീവിക്കുന്ന സുസ്ഥിര വസ്തുക്കളും എഞ്ചിനീയറിംഗും.',
