  'site.team.bio2': 'സുസ്ഥിര ഭവനത്തിലെ അവാർഡ് നേടിയ പ്രവൃത്തിയോടെ ഡിസൈൻ സ്റ്റുഡിയോയെ നയിക്കുന്നു.',
  'site.team.bio3': 'ഭൂകമ്പ മേഖലകൾക്കും കനത്ത ഇൻഫ്രാസ്ട്രക്ചറിനുമുള്ള സ്ട്രക്ചറൽ സ്പെഷ്യലിസ്റ്റ്.',
