  'site.why.hero.sub': 'ബിൽഡറെ തിരഞ്ഞെടുക്കുന്നത് വിശ്വാസത്തിന്റെ ചാട്ടമാണ്. അതിനെ രേഖപ്പെടുത്തിയ, ഓഡിറ്റ് ചെയ്ത, വാറന്റി ഉള്ള തീരുമാനമാക്കി ഞങ്ങൾ മാറ്റുന്നു.',
