  'award.workStartedOwnerNote': 'ഈ പ്രോജക്റ്റിൽ ജോലി രേഖപ്പെടുത്തിയിട്ടുണ്ട്, പക്ഷേ {name} ഇതുവരെ കരാർ സ്ഥിരീകരിച്ചിട്ടില്ല. അവർ സ്ഥിരീകരിക്കുന്നതുവരെ സ്ഥിരീകരിച്ച കരാർ തുകയില്ല.',
