  'award.confirmFinalQuotationSub': 'അന്തിമ ക്വട്ടേഷൻ സ്ഥിരീകരിക്കുക. നിങ്ങൾ സ്ഥിരീകരിച്ചതിനു ശേഷം മാത്രമേ ഉടമയ്ക്ക് പ്രോജക്റ്റ് ഏൽപ്പിക്കാനാകൂ.',
