  'award.dialog.confirmQuotationTitle': 'അന്തിമ ക്വട്ടേഷൻ സ്ഥിരീകരിക്കുക',
  'award.dialog.confirmQuotationBody': 'സ്ഥിരീകരിക്കുന്നതിലൂടെ, ഈ പ്രോജക്റ്റ് {amount}-ന് ഏറ്റെടുക്കാൻ നിങ്ങൾ സമ്മതിക്കുന്നു. തുടർന്ന് ഇത് നിങ്ങളെ ഏൽപ്പിക്കണോ എന്ന് ഉടമ തീരുമാനിക്കും; അവർ ഏൽപ്പിക്കുന്നതുവരെ ഒന്നും ഏൽപ്പിക്കപ്പെടുന്നില്ല.',
