  'landing.footer.tagline': 'ഇന്ത്യയ്ക്കായുള്ള ബന്ധിപ്പിച്ച നിർമ്മാണ പ്ലാറ്റ്ഫോം. നിർമ്മിക്കാൻ നിങ്ങൾക്ക് വേണ്ടതെല്ലാം — വീട്ടുടമകൾ, ബിൽഡർമാർ, എൻജിനീയർമാർ, വിതരണക്കാർ, ഉപകരണ ഉടമകൾ, എല്ലാവരും ഒരിടത്ത്.',
