  'site.calculators.vastu.principle.masterBedroom': 'ഭാരവും സ്ഥിരതയുമായി ബന്ധപ്പെടുത്തുന്ന തെക്കുപടിഞ്ഞാറാണ് വീട്ടിലെ കാരണവർക്കുള്ള പരമ്പരാഗത സ്ഥാനം; വടക്കുകിഴക്കാണ് ഏറ്റവും അനുയോജ്യമല്ലാത്തത്.',
  'site.calculators.vastu.principle.childrensBedroom': 'കുട്ടികളുടെ മുറിക്ക് വടക്കുപടിഞ്ഞാറും തെക്കുകിഴക്കുമാണ് പരമ്പരാഗത തിരഞ്ഞെടുപ്പുകൾ; വീട്ടിലെ കാരണവർക്കായി മാറ്റിവച്ചിരിക്കുന്ന തെക്കുപടിഞ്ഞാറാണ് ഏറ്റവും അനുയോജ്യമല്ലാത്തത്.',
  'site.calculators.vastu.principle.guestRoom': 'ചലനവുമായും ഹ്രസ്വ താമസവുമായും ബന്ധപ്പെടുത്തുന്ന വടക്കുപടിഞ്ഞാറ് അതിഥി മുറിക്ക് അനുയോജ്യമാണ്; തെക്കുപടിഞ്ഞാറാണ് ഏറ്റവും അനുയോജ്യമല്ലാത്തത്.',
  'site.calculators.vastu.principle.diningRoom': 'ഊണുമുറി പരമ്പരാഗതമായി അടുക്കളയോട് ചേർന്ന് കിഴക്കോ വടക്കോ ഭാഗത്താണ് വരുന്നത്; തെക്കുപടിഞ്ഞാറാണ് ഏറ്റവും അനുയോജ്യമല്ലാത്തത്.',
  'site.calculators.vastu.principle.well': 'ജലവുമായി ബന്ധപ്പെട്ട ദിശയായ വടക്കുകിഴക്കാണ് ജലസ്രോതസ്സുകൾ പരമ്പരാഗതമായി ഒരുക്കുന്നത്; തെക്കുപടിഞ്ഞാറാണ് ഏറ്റവും അനുയോജ്യമല്ലാത്തത്.',
  'site.calculators.vastu.principle.toilet': 'ശുചിമുറികൾ പരമ്പരാഗതമായി വടക്കുപടിഞ്ഞാറോ പടിഞ്ഞാറോ ഭാഗത്ത്, ഏറ്റവും പവിത്രമായി കണക്കാക്കുന്ന വടക്കുകിഴക്ക് മൂലയിൽ നിന്ന് അകലെയാണ് ഒരുക്കുന്നത്.',
  'site.calculators.vastu.principle.garage': 'വാഹന പാർക്കിങ് പരമ്പരാഗതമായി വടക്കുപടിഞ്ഞാറ് ഭാഗത്താണ് ഒരുക്കുന്നത്; തെക്കുപടിഞ്ഞാറാണ് ഏറ്റവും അനുയോജ്യമല്ലാത്തത്.',
  'site.calculators.vastu.principle.houseInPlot': 'പണിത ഭാഗം പരമ്പരാഗതമായി പ്ലോട്ടിന്റെ തെക്കുപടിഞ്ഞാറ് ഭാഗത്തേക്ക് ചേർന്നാണ് വരുന്നത്, തുറസ്സായ സ്ഥലം വടക്കുകിഴക്ക് ഭാഗത്ത് വിടുന്നു.',
