  'site.calculators.vastu.advicePreferred': 'പരമ്പരാഗതമായി അഭികാമ്യം: {best}. {principle}',
  'site.calculators.vastu.or': ' അല്ലെങ്കിൽ ',
  'site.calculators.vastu.title': 'വാസ്തു കാൽക്കുലേറ്റർ',
  'site.calculators.vastu.intro': 'നിങ്ങളുടെ വീടിന്റെ ഓരോ ഭാഗവും ഏത് ദിശയിലാണെന്ന് തിരഞ്ഞെടുക്കുക, പരമ്പരാഗത വാസ്തു ദിശാ തത്ത്വങ്ങൾക്കനുസരിച്ച് ആ സ്ഥാനങ്ങൾക്ക് എത്ര സ്കോർ ലഭിക്കുന്നു എന്ന് കാണുക.',
